object NovenaData143 {
    val novena: Novena = Novena(
        id = """novena-a-santa-brigida-de-suecia""",
        title = LocalizedText("""Novena a Santa Brígida de Suecia""", """St. Bridget of Sweden Novena""", """Novena a Santa Brígida da Suécia"""),
        patron = LocalizedText("""Santo patrón de Europa, Suecia, las viudas y la buena muerte""", """Patron saint of Europe, Sweden, Widows, holy death""", """Novena a Santa Brígida da Suécia"""),
        category = LocalizedText("""Novenas""", """Novenas""", """Novenas"""),
        description = LocalizedText("""Santa Brígida de Suecia, nacida Birgitta, fue una mística sueca y fundadora de una orden religiosa que vivió en el siglo XIV y recibió visiones especiales de Jesucristo.""", """St Bridget of Sweden, born Birgitta, was a Swedish mystic and religious Order foundress who lived in the 1300s and was gifted with special visions from Jesus Christ.""", """Santo padroeiro de a Europa, a Suécia, as viúvas e a boa morte"""),
        miraculousHistory = LocalizedText("", "", ""),
        promises = LocalizedText("", "", ""),
        days = listOf(
            NovenaDay(
                dayNumber = 1,
                theme = LocalizedText("""Día 1""", """Day 1""", """Dia 1"""),
                scripture = "",
                meditation = LocalizedText("""En el nombre del Padre, y del Hijo, y del Espíritu Santo.

Amén.

Primera oración

Padre nuestro. Dios te salve, María.

¡Oh Jesucristo! Dulzura eterna de los que te aman, gozo que supera todo gozo y todo deseo, Salvación y Esperanza de todos los pecadores, que has demostrado que no tienes mayor deseo que estar entre los hombres, hasta el punto de asumir la naturaleza humana en la plenitud de los tiempos por amor a los hombres: recuerda todos los sufrimientos que soportaste desde el instante de tu concepción, y especialmente durante tu Pasión, tal como fue decretado y ordenado desde toda la eternidad en el plan divino.

Recuerda, oh Señor, que durante la Última Cena con tus discípulos, después de lavarles los pies, les diste tu santísimo Cuerpo y tu preciosísima Sangre, y mientras los consolabas con dulzura, les anunciaste tu próxima Pasión.

Recuerda la tristeza y la amargura que experimentaste en tu alma, como tú mismo lo atestiguaste diciendo: “Mi alma está triste hasta la muerte.”

Recuerda todo el temor, la angustia y el dolor que sufriste en tu delicado Cuerpo antes del tormento de la crucifixión, cuando, después de haber orado tres veces, bañado en un sudor de sangre, fuiste traicionado por Judas, tu discípulo, apresado por el pueblo de una nación que habías escogido y enaltecido, acusado por falsos testigos e injustamente juzgado por tres jueces en la flor de tu juventud y en el tiempo solemne de la Pascua.

Recuerda que fuiste despojado de tus vestiduras y vestido con ropas de burla; que te vendaron el rostro y los ojos, que te abofetearon, te coronaron de espinas, te pusieron una caña en las manos, que fuiste molido a golpes y colmado de afrentas y ultrajes.

En memoria de todas estas penas y sufrimientos que soportaste antes de tu Pasión en la Cruz, concédeme antes de mi muerte una verdadera contrición, una confesión sincera y completa, una digna satisfacción y el perdón de todos mis pecados. Amén.

Segunda oración

Padre nuestro. Dios te salve, María.

¡Oh Jesús! Verdadera libertad de los ángeles, Paraíso de delicias, recuerda el horror y la tristeza que soportaste cuando tus enemigos, como leones furiosos, te rodearon y con miles de insultos, salivazos, golpes, desgarros y otras crueldades inauditas te atormentaron a su antojo. En consideración de estos tormentos y palabras injuriosas, te suplico, oh Salvador mío, que me libres de todos mis enemigos, visibles e invisibles, y que me conduzcas, bajo tu protección, a la perfección de la salvación eterna. Amén.

Tercera oración

Padre nuestro. Dios te salve, María.

¡Oh Jesús! Creador del cielo y de la tierra, a quien nada puede abarcar ni limitar, tú que envuelves y sostienes todo bajo tu amoroso poder, recuerda el dolor amarguísimo que sufriste cuando los judíos clavaron tus sagradas manos y pies a la Cruz, golpe tras golpe, con grandes clavos sin punta, y no encontrándote en un estado lo bastante lastimoso para saciar su furor, agrandaron tus llagas, añadieron dolor al dolor, y con indescriptible crueldad extendieron tu Cuerpo sobre la Cruz, tirando de ti por todos lados y dislocando así tus miembros.

Te suplico, oh Jesús, por el recuerdo de este amorosísimo sufrimiento de la Cruz, que me concedas la gracia de temerte y de amarte. Amén.

Cuarta oración

Padre nuestro. Dios te salve, María.

¡Oh Jesús! Médico celestial, elevado en la Cruz para sanar nuestras heridas con las tuyas, recuerda las contusiones que sufriste y la debilidad de todos tus miembros, que fueron estirados hasta tal punto que nunca hubo dolor semejante al tuyo. Desde la coronilla de tu cabeza hasta las plantas de tus pies no hubo un solo lugar de tu Cuerpo que no estuviera atormentado, y sin embargo, olvidando todos tus sufrimientos, no dejaste de orar a tu Padre celestial por tus enemigos, diciendo: “Padre, perdónalos, porque no saben lo que hacen.”

Por esta gran misericordia, y en memoria de este sufrimiento, concede que el recuerdo de tu amarguísima Pasión obre en nosotros una perfecta contrición y el perdón de todos nuestros pecados. Amén.

Quinta oración

Padre nuestro. Dios te salve, María.

¡Oh Jesús! Espejo del esplendor eterno, recuerda la tristeza que sentiste cuando, contemplando a la luz de tu divinidad la predestinación de los que se salvarían por los méritos de tu sagrada Pasión, viste al mismo tiempo la gran multitud de réprobos que se condenarían por sus pecados, y te lamentaste amargamente por aquellos pecadores desdichados y perdidos sin esperanza.

Por el abismo de compasión y de piedad, y especialmente por la bondad que mostraste al buen ladrón cuando le dijiste: “Hoy estarás conmigo en el Paraíso”, te suplico, oh dulce Jesús, que en la hora de mi muerte tengas misericordia de mí. Amén.

Sexta oración

Padre nuestro. Dios te salve, María.

¡Oh Jesús! Rey amado y sumamente deseable, recuerda el dolor que sufriste cuando, desnudo y como un vulgar criminal, fuiste clavado y levantado en la Cruz, cuando todos tus parientes y amigos te abandonaron, excepto tu amada Madre, que permaneció junto a ti durante tu agonía y a quien encomendaste a tu fiel discípulo cuando dijiste a María: “Mujer, ahí tienes a tu hijo”, y a San Juan: “Ahí tienes a tu madre.”

Te suplico, oh Salvador mío, por la espada de dolor que traspasó el alma de tu santa Madre, que tengas compasión de mí en todas mis aflicciones y tribulaciones, tanto corporales como espirituales, y que me asistas en todas mis pruebas, y especialmente en la hora de mi muerte. Amén.

Séptima oración

Padre nuestro. Dios te salve, María.

¡Oh Jesús! Fuente inagotable de compasión, que con un profundo gesto de amor dijiste desde la Cruz: “¡Tengo sed!”, sufriendo sed por la salvación del género humano: te suplico, oh Salvador mío, que inflames en nuestros corazones el deseo de tender a la perfección en todas nuestras obras, y que extingas en nosotros la concupiscencia de la carne y el ardor de los deseos mundanos. Amén.

(menciona tu petición aquí…)

Octava oración

Padre nuestro. Dios te salve, María.

¡Oh Jesús! Dulzura de los corazones, deleite del espíritu, por la amargura del vinagre y de la hiel que probaste en la Cruz por amor a nosotros, concédenos la gracia de recibir dignamente tu preciosísimo Cuerpo y Sangre durante nuestra vida y en la hora de nuestra muerte, para que nos sirvan de remedio y consuelo para nuestras almas. Amén.

Novena oración

Padre nuestro. Dios te salve, María.

¡Oh Jesús! Virtud real, gozo del alma, recuerda el dolor que soportaste cuando, sumergido en un océano de amargura al acercarse la muerte, insultado y ultrajado por los judíos, clamaste en alta voz que habías sido abandonado por tu Padre, diciendo: “Dios mío, Dios mío, ¿por qué me has abandonado?”

Por esta angustia, te suplico, oh Salvador mío, que no me abandones en los terrores y dolores de mi muerte. Amén.

Décima oración

Padre nuestro. Dios te salve, María.

¡Oh Jesús! Que eres el principio y el fin de todas las cosas, la vida y la virtud, recuerda que por nosotros fuiste sumergido en un abismo de sufrimiento desde las plantas de los pies hasta la coronilla de la cabeza. En consideración de la enormidad de tus llagas, enséñame a guardar, por puro amor, tus mandamientos, cuyo camino es ancho y fácil para los que te aman. Amén.

Undécima oración

Padre nuestro. Dios te salve, María.

¡Oh Jesús! Abismo profundo de misericordia, te suplico, en memoria de tus llagas, que penetraron hasta la médula de tus huesos y hasta lo más hondo de tu ser, que me apartes del pecado a mí, miserable pecador, abrumado por mis ofensas, y que me escondas de tu rostro justamente irritado contra mí; escóndeme en tus llagas hasta que hayan pasado tu ira y tu justa indignación. Amén.

Duodécima oración

Padre nuestro. Dios te salve, María.

¡Oh Jesús! Espejo de la verdad, signo de unidad, vínculo de caridad, recuerda la multitud de llagas con que fuiste cubierto de pies a cabeza, desgarrado y enrojecido por el derramamiento de tu adorable Sangre. ¡Oh grande y universal dolor que sufriste en tu carne virginal por amor a nosotros! ¡Dulcísimo Jesús! ¿Qué hay que pudieras haber hecho por nosotros y que no hayas hecho? Que el fruto de tus sufrimientos se renueve en mi alma por el fiel recuerdo de tu Pasión, y que tu amor crezca en mi corazón cada día, hasta que te vea en la eternidad, tú que eres el tesoro de todo verdadero bien y de toda alegría, que te ruego me concedas, oh dulcísimo Jesús, en el cielo. Amén.

Decimotercera oración

Padre nuestro. Dios te salve, María.

¡Oh Jesús! León fuerte, Rey inmortal e invencible, recuerda el dolor que soportaste cuando, agotadas por completo todas tus fuerzas, tanto morales como físicas, inclinaste la cabeza diciendo: “¡Todo está consumado!”

Por esta angustia y dolor, te suplico, Señor Jesús, que tengas misericordia de mí en la hora de mi muerte, cuando mi mente esté muy turbada y mi alma en angustia. Amén.

Decimocuarta oración

Padre nuestro. Dios te salve, María.

¡Oh Jesús! Hijo único del Padre, esplendor e imagen de su sustancia, recuerda la sencilla y humilde recomendación que hiciste de tu alma a tu Padre eterno, diciendo: “¡Padre, en tus manos encomiendo mi espíritu!” Y con tu Cuerpo todo desgarrado, tu Corazón quebrantado y las entrañas de tu misericordia abiertas para redimirnos, expiraste. Por esta preciosa muerte, te suplico, oh Rey de los santos, que me consueles y me ayudes a resistir al demonio, a la carne y al mundo, para que, muerto al mundo, viva solo para ti. Te suplico que en la hora de mi muerte me recibas a mí, peregrino y desterrado que vuelve a ti. Amén.

Decimoquinta oración

Padre nuestro. Dios te salve, María.

¡Oh Jesús! ¡Vid verdadera y fecunda! Recuerda la abundante efusión de sangre que tan generosamente derramaste de tu sagrado Cuerpo, como el jugo de las uvas en el lagar.

De tu costado, traspasado por la lanza de un soldado, brotaron sangre y agua hasta que no quedó en tu Cuerpo ni una sola gota, y finalmente, como un manojo de mirra elevado a lo alto de la Cruz, tu delicada carne fue destruida, la sustancia misma de tu Cuerpo se marchitó y la médula de tus huesos se secó.

Por esta amarga Pasión y por la efusión de tu preciosa Sangre, te suplico, oh dulce Jesús, que recibas mi alma cuando esté en la agonía de la muerte. Amén.

Conclusión

¡Oh dulce Jesús! Traspasa mi corazón, para que mis lágrimas de penitencia y de amor sean mi pan de día y de noche; que me convierta enteramente a ti, que mi corazón sea tu morada perpetua, que mi conversación te sea agradable, y que el fin de mi vida sea tan digno de alabanza que merezca el cielo y allí, con tus santos, te alabe para siempre. Amén.

En el nombre del Padre, y del Hijo, y del Espíritu Santo.

Amén.

