Jul 23rd""", """Continue esta novena no app

Configure lembretes para não perder nenhum dia

Em nome do Pai, do Filho e do Espírito Santo.

Amém.

Primeira Oração

Pai-Nosso. Ave-Maria.

Ó Jesus Cristo! Eterna Doçura dos que Vos amam, alegria que supera toda alegria e todo desejo, Salvação e Esperança de todos os pecadores, que mostrastes não ter maior desejo do que estar entre os homens, chegando a assumir a natureza humana na plenitude dos tempos por amor dos homens, lembrai-Vos de todos os sofrimentos que suportastes desde o instante da Vossa concepção, e especialmente durante a Vossa Paixão, tal como foi decretada e ordenada desde toda a eternidade no plano divino.

Lembrai-Vos, Senhor, de que durante a Última Ceia com os Vossos discípulos, depois de lhes lavar os pés, lhes destes o Vosso Preciosíssimo Corpo e Sangue e, ao mesmo tempo que os consoláveis docemente, lhes predissestes a Vossa Paixão iminente.

Lembrai-Vos da tristeza e da amargura que experimentastes em Vossa Alma, como Vós mesmo testemunhastes, dizendo: “A Minha alma está triste até a morte.”

Lembrai-Vos de todo o temor, angústia e dor que sofrestes em Vosso delicado Corpo antes do tormento da crucifixão, quando, depois de terdes rezado três vezes, banhado num suor de sangue, fostes traído por Judas, Vosso discípulo, preso pelo povo de uma nação que havíeis escolhido e exaltado, acusado por falsas testemunhas, injustamente julgado por três juízes, na flor da Vossa juventude e no solene tempo pascal.

Lembrai-Vos de que fostes despojado das Vossas vestes e vestido com as do escárnio; de que Vos vendaram o Rosto e os Olhos, de que fostes esbofeteado, coroado de espinhos, de que Vos puseram uma cana nas Mãos, de que fostes moído de golpes e cumulado de afrontas e ultrajes.

Em memória de todas essas penas e sofrimentos que suportastes antes da Vossa Paixão na Cruz, concedei-me, antes da minha morte, uma verdadeira contrição, uma confissão sincera e íntegra, uma digna satisfação e a remissão de todos os meus pecados. Amém.

Segunda Oração

Pai-Nosso. Ave-Maria.

Ó Jesus! Verdadeira liberdade dos anjos, Paraíso de delícias, lembrai-Vos do horror e da tristeza que suportastes quando os Vossos inimigos, como leões furiosos, Vos cercaram e, com milhares de insultos, escarros, bofetadas, dilacerações e outras crueldades inauditas, Vos atormentaram à vontade. Em consideração desses tormentos e palavras injuriosas, eu Vos suplico, ó meu Salvador, que me livreis de todos os meus inimigos, visíveis e invisíveis, e me conduzais, sob a Vossa proteção, à perfeição da salvação eterna. Amém.

Terceira Oração

Pai-Nosso. Ave-Maria.

Ó Jesus! Criador do Céu e da terra, a quem nada pode conter nem limitar, Vós que envolveis e sustentais todas as coisas sob o Vosso amoroso poder, lembrai-Vos da dor amaríssima que sofrestes quando os judeus pregaram na Cruz as Vossas Sagradas Mãos e Pés, golpe após golpe, com grandes cravos rombudos e, não Vos achando num estado bastante lastimável para saciar a sua raiva, alargaram as Vossas Chagas, acrescentaram dor à dor e, com indescritível crueldade, estenderam o Vosso Corpo na Cruz, puxando-Vos de todos os lados e deslocando assim os Vossos Membros.

Eu Vos peço, ó Jesus, pela memória desse amorosíssimo sofrimento da Cruz, que me concedais a graça de Vos temer e de Vos amar. Amém.

Quarta Oração

Pai-Nosso. Ave-Maria.

Ó Jesus! Médico celeste, elevado na Cruz para curar as nossas feridas com as Vossas, lembrai-Vos das contusões que sofrestes e da fraqueza de todos os Vossos Membros, que foram distendidos a tal ponto que jamais houve dor semelhante à Vossa. Do alto da Vossa Cabeça até a planta dos Vossos Pés não havia um só lugar do Vosso Corpo que não estivesse em tormento e, no entanto, esquecendo todos os Vossos sofrimentos, não cessastes de rezar ao Vosso Pai celeste pelos Vossos inimigos, dizendo: “Pai, perdoai-lhes, porque não sabem o que fazem.”

Por essa grande Misericórdia, e em memória desse sofrimento, concedei que a lembrança da Vossa amaríssima Paixão opere em nós uma perfeita contrição e a remissão de todos os nossos pecados. Amém.

Quinta Oração

Pai-Nosso. Ave-Maria.

Ó Jesus! Espelho do esplendor eterno, lembrai-Vos da tristeza que experimentastes quando, contemplando à luz da Vossa Divindade a predestinação dos que seriam salvos pelos méritos da Vossa Sagrada Paixão, vistes ao mesmo tempo a grande multidão dos réprobos que seriam condenados pelos seus pecados, e Vos lamentastes amargamente por esses pecadores desesperados e infelizes.

Por esse abismo de compaixão e piedade, e especialmente pela bondade que mostrastes ao bom ladrão quando lhe dissestes: “Hoje estarás comigo no Paraíso”, eu Vos suplico, ó doce Jesus, que na hora da minha morte useis de misericórdia para comigo. Amém.

Sexta Oração

Pai-Nosso. Ave-Maria.

Ó Jesus! Rei amado e sumamente desejável, lembrai-Vos da dor que sofrestes quando, nu e como um criminoso comum, fostes pregado e levantado na Cruz, quando todos os Vossos parentes e amigos Vos abandonaram, exceto a Vossa amada Mãe, que permaneceu junto de Vós durante a Vossa agonia e que confiastes ao Vosso fiel discípulo, quando dissestes a Maria: “Mulher, eis aí o teu filho!” e a São João: “Filho, eis aí a tua Mãe!”

Eu Vos suplico, ó meu Salvador, pela espada de dor que traspassou a alma da Vossa santa Mãe, que tenhais compaixão de mim em todas as minhas aflições e tribulações, tanto corporais como espirituais, e que me assistais em todas as minhas provações, e especialmente na hora da minha morte. Amém.

Sétima Oração

Pai-Nosso. Ave-Maria.

Ó Jesus! Fonte inesgotável de compaixão, que, num profundo gesto de Amor, dissestes na Cruz: “Tenho sede!”, sofrendo a sede da salvação do gênero humano, eu Vos suplico, ó meu Salvador, que inflameis os nossos corações no desejo de tender à perfeição em todos os nossos atos, e que extingais em nós a concupiscência da carne e o ardor dos desejos mundanos. Amém.

(mencione o pedido aqui…)

Oitava Oração

Pai-Nosso. Ave-Maria.

Ó Jesus! Doçura dos corações, deleite do espírito, pela amargura do vinagre e do fel que provastes na Cruz por amor de nós, concedei-nos a graça de receber dignamente o Vosso Precioso Corpo e Sangue durante a nossa vida e na hora da nossa morte, para que nos sirvam de remédio e consolo para as nossas almas. Amém.

Nona Oração

Pai-Nosso. Ave-Maria.

Ó Jesus! Virtude real, alegria da mente, lembrai-Vos da dor que suportastes quando, mergulhado num oceano de amargura à aproximação da morte, insultado e ultrajado pelos judeus, clamastes em alta voz que fostes abandonado pelo Vosso Pai, dizendo: “Meu Deus, Meu Deus, por que Me abandonastes?”

Por essa angústia, eu Vos suplico, ó meu Salvador, que não me abandoneis nos terrores e nas dores da minha morte. Amém.

Décima Oração

Pai-Nosso. Ave-Maria.

Ó Jesus! Vós que sois o princípio e o fim de todas as coisas, vida e virtude, lembrai-Vos de que por nós fostes mergulhado num abismo de sofrimento, da planta dos Pés até o alto da Cabeça. Em consideração da enormidade das Vossas Chagas, ensinai-me a guardar, por puro amor, os Vossos Mandamentos, cujo caminho é largo e fácil para os que Vos amam. Amém.

Décima Primeira Oração

Pai-Nosso. Ave-Maria.

Ó Jesus! Abismo profundo de misericórdia, eu Vos suplico, em memória das Vossas Chagas, que penetraram até a medula dos Vossos Ossos e até o mais íntimo do Vosso ser, que me afasteis do pecado, a mim, miserável pecador, oprimido pelas minhas ofensas, e me escondais da Vossa Face, justamente irritada contra mim; escondei-me nas Vossas Chagas, até que passem a Vossa ira e a Vossa justa indignação. Amém.

Décima Segunda Oração

Pai-Nosso. Ave-Maria.

Ó Jesus! Espelho da Verdade, sinal de unidade, vínculo da Caridade, lembrai-Vos da multidão de chagas de que fostes coberto da cabeça aos pés, dilacerado e avermelhado pelo derramamento do Vosso adorável Sangue. Ó grande e universal Dor que sofrestes em Vossa Carne virginal por amor de nós! Dulcíssimo Jesus! Que poderíeis ter feito por nós que não tenhais feito! Que o fruto dos Vossos sofrimentos se renove em minha alma pela fiel lembrança da Vossa Paixão, e que o Vosso Amor cresça em meu coração a cada dia, até que eu Vos veja na eternidade, Vós que sois o tesouro de todo verdadeiro bem e de toda alegria, que Vos peço me concedais, ó dulcíssimo Jesus, no Céu. Amém.

Décima Terceira Oração

Pai-Nosso. Ave-Maria.

Ó Jesus! Leão forte, Rei imortal e invencível, lembrai-Vos da dor que suportastes quando, esgotadas inteiramente todas as Vossas forças, tanto morais como físicas, inclinastes a Cabeça, dizendo: “Tudo está consumado!”

Por essa angústia e dor, eu Vos suplico, Senhor Jesus, que tenhais misericórdia de mim na hora da minha morte, quando a minha mente estará muito perturbada e a minha alma estará em angústia. Amém.

Décima Quarta Oração

Pai-Nosso. Ave-Maria.

Ó Jesus! Filho único do Pai, Esplendor e figura da Sua Substância, lembrai-Vos da simples e humilde recomendação que fizestes da Vossa Alma ao Vosso Pai Eterno, dizendo: “Pai, em Vossas mãos entrego o Meu espírito!” E, com o Corpo todo dilacerado, o Coração partido e as entranhas da Vossa Misericórdia abertas para nos remir, expirastes. Por essa Preciosa Morte, eu Vos suplico, ó Rei dos Santos, confortai-me e ajudai-me a resistir ao demônio, à carne e ao mundo, para que, morto para o mundo, eu viva só para Vós. Eu Vos suplico que, na hora da minha morte, me recebais, peregrino e exilado que volta para Vós. Amém.

Décima Quinta Oração

Pai-Nosso. Ave-Maria.

Ó Jesus! Videira verdadeira e fecunda! Lembrai-Vos da abundante efusão de Sangue que tão generosamente derramastes do Vosso Sagrado Corpo, como o suco das uvas no lagar.

Do Vosso Lado, traspassado pela lança de um soldado, saíram sangue e água até que não restou em Vosso Corpo uma só gota e, por fim, como um feixe de mirra elevado ao alto da Cruz, a Vossa delicada Carne foi destruída, a própria Substância do Vosso Corpo murchou e a Medula dos Vossos Ossos secou.

Por essa amarga Paixão e pela efusão do Vosso Precioso Sangue, eu Vos suplico, ó doce Jesus, que recebais a minha alma quando eu estiver na agonia da morte. Amém.

Conclusão

Ó doce Jesus! Traspassai o meu coração, para que as minhas lágrimas de penitência e de amor sejam o meu pão dia e noite; que eu me converta inteiramente a Vós, que o meu coração seja a Vossa perpétua morada, que a minha conversação Vos seja agradável, e que o fim da minha vida seja tão digno de louvor que eu mereça o Céu e ali, com os Vossos santos, Vos louve para sempre. Amém.

Em nome do Pai, do Filho e do Espírito Santo.

Amém.

